import java.util.*

var memo = Array(2) { BooleanArray(0) }
lateinit var dp: Array<LongArray>

fun solve(n: Int, k: Int, d: Int, flag: Boolean): Long {
    val flagIndex = if (flag) 1 else 0
    if (dp[flagIndex][n] != -1L) return dp[flagIndex][n]
    if (n == 0 && flag) return 1L.also { dp[flagIndex][n] = it }
    if (n == 0 && !flag) return 0L.also { dp[flagIndex][n] = it }

    var cnt = 0L
    for (i in 1..k) {
        if (n - i >= 0) {
            cnt += solve(n - i, k, d, flag || (i >= d))
            cnt %= 1000000007
        }
    }
    dp[flagIndex][n] = cnt
    return cnt
}

fun solution(n: Int, k: Int, d: Int): Long {
    dp = Array(2) { LongArray(n + 1) { -1L } }
    solve(n, k, d, false)
    return dp[0][n] % 1000000007
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val k = scanner.nextInt()
    val d = scanner.nextInt()
    println(solution(n, k, d))
}

